package com.circle.oog;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class ExpandedEngineeringServiceTest {
    final ObjectMapper json=new ObjectMapper();
    List<ExpandedEngineeringService.Pad> pads(){return List.of(pad("A",0,0,10000),pad("B",10000,0,10000),pad("C",0,4000,10000),pad("D",10000,4000,10000));}
    ExpandedEngineeringService.Pad pad(String id,double x,double y,double k){return new ExpandedEngineeringService.Pad(id,x,y,k,100000d,10d,1000d);}
    ExpandedEngineeringService.Beam beam(String id,List<String> padIds){return new ExpandedEngineeringService.Beam(id,padIds,"X",-1000d,11000d,200000d,1e10,1e8,1e6,100d,100d,10d,1000d,true,"Verified beam section, effective shear area, restraints and applicability fixture");}
    ExpandedEngineeringService.Input input(String mode,double mass,double z,List<ExpandedEngineeringService.Pad> pads,List<ExpandedEngineeringService.Beam> beams){return new ExpandedEngineeringService.Input(UUID.randomUUID(),mode,"Measured mass/CoG/support stiffness evidence","Numerical fixture",mass,5000d,2000d,z,1d,true,true,"Separate external-load and excluded-mode review fixture",new ExpandedEngineeringService.Footprint(0d,10000d,0d,4000d,0d,"Actual support rectangle fixture"),pads,List.of(new ExpandedEngineeringService.Leg("ROAD1","ROAD","Confirmed route fixture",true,1d,"Maximum compression envelope fixture",null)),List.of(),beams);}
    com.fasterxml.jackson.databind.JsonNode cargo()throws Exception{return json.readTree("{\"length\":10000,\"width\":4000,\"height\":3000,\"grossWeight\":1000}");}
    @Test void fourDirectionRouteProducesKnownQuasiStaticReactionsAndPreservesPrePlan()throws Exception{
        var result=ExpandedEngineeringService.calculate(input("CONFIRMED",1000,1000,pads(),List.of(beam("B1",List.of("A","B")),beam("B2",List.of("C","D")))),cargo());
        assertThat(result).containsEntry("eligibleForInternalApproval",true).containsEntry("carrierApproved",false).containsEntry("planStatus","PRE_PLAN");
        var cases=(List<Map<String,Object>>)result.get("loadCases");assertThat(cases).hasSize(4);var forward=cases.getFirst();assertThat((double)forward.get("externalForceKn")).isCloseTo(7.848,within(1e-10));
        var support=(Map<String,Object>)((List<?>)forward.get("supportCases")).getFirst();var contact=(Map<String,Object>)support.get("pads");var rows=(List<Map<String,Object>>)contact.get("pads");
        assertThat((double)rows.get(0).get("reactionKn")).isCloseTo(2.0601,within(1e-9));assertThat((double)rows.get(1).get("reactionKn")).isCloseTo(2.8449,within(1e-9));assertThat((double)contact.get("forceResidualKn")).isCloseTo(0,within(1e-9));
    }
    @Test void ctuProfilesKeepDirectionSpecificMinimumNormalCoefficients(){var c=ExpandedEngineeringService.coefficients("SEA_C",null);assertThat(c.forward()).isEqualTo(.4);assertThat(c.verticalLongitudinal()).isEqualTo(.2);assertThat(c.verticalTransverse()).isEqualTo(1);assertThat(ExpandedEngineeringService.profiles()).hasSize(5);}
    @Test void equalFourPadsShareCentralLoadEquallyAndRespectMomentEquilibrium(){var r=ExpandedEngineeringService.solvePads(pads(),100,500000,200000);assertThat(r).containsEntry("equilibriumFound",true).containsEntry("withinDeclaredLimits",true);var rows=(List<Map<String,Object>>)r.get("pads");for(var row:rows)assertThat((double)row.get("reactionKn")).isCloseTo(25,within(1e-9));}
    @Test void stiffnessCompatibilityAvoidsArbitraryEqualSharing(){var p=List.of(pad("A",0,0,10000),pad("B",10000,0,10000),pad("C",0,4000,10000),pad("D",10000,4000,20000));var r=ExpandedEngineeringService.solvePads(p,100,500000,200000);var rows=(List<Map<String,Object>>)r.get("pads");assertThat((double)rows.get(0).get("reactionKn")).isCloseTo(28.5714285714,within(1e-8));assertThat((double)rows.get(3).get("reactionKn")).isCloseTo(28.5714285714,within(1e-8));assertThat((double)rows.get(1).get("reactionKn")).isCloseTo(21.4285714286,within(1e-8));}
    @Test void outsideSupportHullAndCollinearPadsCannotInventEquilibrium(){assertThat(ExpandedEngineeringService.solvePads(pads(),100,1100000,200000)).containsEntry("equilibriumFound",false);var p=List.of(pad("A",0,0,1),pad("B",5000,0,1),pad("C",10000,0,1));assertThat(ExpandedEngineeringService.solvePads(p,100,500000,0)).containsEntry("equilibriumFound",false);}
    @Test void unloadingContactSetsCheckInactivePads(){var p=pads();var r=ExpandedEngineeringService.solvePads(p,100,800000,320000);assertThat(r).containsEntry("equilibriumFound",true);var rows=(List<Map<String,Object>>)r.get("pads");assertThat(rows.get(0)).containsEntry("inContact",false).containsEntry("reactionKn",0d);assertThat((double)r.get("momentXResidualKnMm")).isCloseTo(0,within(1e-7));}
    @Test void centrallyLoadedBeamMatchesClassicalClosedForm(){var b=new ExpandedEngineeringService.Beam("S",List.of("P"),"X",0d,1000d,200000d,1e6,10000d,1000d,1000d,1000d,100d,1000d,true,"test");var p=List.of(pad("P",500,0,10000));var r=ExpandedEngineeringService.beam(b,p,List.of(Map.of("id","P","reactionKn",10d)));assertThat((double)r.get("leftReactionKn")).isEqualTo(5);assertThat((double)r.get("maxMomentKnM")).isCloseTo(2.5,within(1e-12));assertThat((double)r.get("maxDeflectionMm")).isCloseTo(10000d*Math.pow(1000,3)/(48*200000*1e6),within(1e-10));assertThat((double)r.get("maxDeflectionAtMm")).isCloseTo(500,within(1e-8));assertThat((double)r.get("bendingStressMpa")).isCloseTo(250,within(1e-9));}
    @Test void offCenterBeamMaximumDeflectionIsNotAssumedAtLoad(){var b=new ExpandedEngineeringService.Beam("S",List.of("P"),"X",0d,1000d,200000d,1e6,10000d,1000d,1000d,1000d,100d,1000d,true,"test");var r=ExpandedEngineeringService.beam(b,List.of(pad("P",250,0,10000)),List.of(Map.of("id","P","reactionKn",10d)));assertThat((double)r.get("maxDeflectionAtMm")).isCloseTo(1000-Math.sqrt((1000000-62500)/3d),within(1e-7));}
    @Test void beamSuperpositionSatisfiesTwoSymmetricPointLoads(){var b=new ExpandedEngineeringService.Beam("S",List.of("P","Q"),"X",0d,1000d,200000d,1e6,10000d,1000d,1000d,1000d,100d,1000d,true,"test");var r=ExpandedEngineeringService.beam(b,List.of(pad("P",250,0,10000),pad("Q",750,0,10000)),List.of(Map.of("id","P","reactionKn",5d),Map.of("id","Q","reactionKn",5d)));assertThat((double)r.get("maxMomentKnM")).isCloseTo(1.25,within(1e-10));assertThat((double)r.get("maxDeflectionAtMm")).isCloseTo(500,within(1e-8));}
    @Test void insufficientLimitsAndMassMismatchNeverApprove()throws Exception{var r=ExpandedEngineeringService.calculate(input("CONFIRMED",500,1000,pads(),List.of(beam("B1",List.of("A","B")),beam("B2",List.of("C","D")))),cargo());assertThat(r).containsEntry("massMatchesSavedCargo",false).containsEntry("eligibleForInternalApproval",false);}
    @Test void estimatedInputIsNotApprovedEvenIfAllNumericsPass()throws Exception{var r=ExpandedEngineeringService.calculate(input("ESTIMATED",1000,1000,pads(),List.of(beam("B1",List.of("A","B")),beam("B2",List.of("C","D")))),cargo());assertThat(r).containsEntry("status","ESTIMATED_REQUIRES_CONFIRMATION").containsEntry("eligibleForInternalApproval",false);}
    @Test void absentRequiredDataReturnsIncompleteRatherThanDefaults()throws Exception{var v=new ExpandedEngineeringService.Input(UUID.randomUUID(),"ESTIMATED",null,"test",null,null,null,null,null,null,null,null,null,null,null,null,null);var r=ExpandedEngineeringService.calculate(v,cargo());assertThat(r).containsEntry("status","INCOMPLETE").containsEntry("eligibleForInternalApproval",false);assertThat((Collection<?>)r.get("missingInputs")).isNotEmpty();}
    @Test void aSingleBeamCannotSilentlyProjectOffAxisPadsIntoOneLine(){var b=beam("B",List.of("A","D"));assertThatThrownBy(()->ExpandedEngineeringService.beam(b,pads(),List.of(Map.of("id","A","reactionKn",1d),Map.of("id","D","reactionKn",1d)))).hasMessageContaining("같은 직선");}
}
